import{z as o,x as B,o as t,c as d,q as r,j as i,D as s,d as E,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"SIMD 自动向量化","description":"","frontmatter":{"title":"SIMD 自动向量化","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cg-simd-autovec.md","filePath":"cs/cg-simd-autovec.md","lastUpdated":1791413859000}'),c={name:"cs/cg-simd-autovec.md"};function C(h,a,p,m,f,D){const A=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="simd-自动向量化" tabindex="-1">SIMD 自动向量化 <a class="header-anchor" href="#simd-自动向量化" aria-label="Permalink to &quot;SIMD 自动向量化&quot;">​</a></h1><div class="epigraph"><p>向量化的一半是依赖分析，另一半是成本模型：前者回答能不能，后者回答值不值；只答前一半的向量化常常是负优化。</p><footer>—— 据 Allen and Kennedy, *Optimizing Compilers for Modern Architectures*；Larsen and Amarasinghe, PLDI, 2000 整理</footer></div><p><a href="/cs/cg-instruction-scheduling">上一课</a>排的是标量指令的次序；本课一次换掉一批——把标量运算折进向量指令。<a href="/cs/auto-vectorization">自动向量化</a>给过循环路线：依赖允许就打 SIMD，处理对齐与余数，成本模型说了算；<a href="/cs/simd-vector">SIMD 与向量</a>给过硬件画面。缺的是三条深路：循环之外怎么打（SLP）、证不出来怎么办（版本化）、宽度不定怎么写（掩码与变长）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>循环向量化只覆盖一类热点：规则的循环、连续访存、可证无依赖。两类常见热点它够不着。一是直线代码里的成对运算——像素通道、定点饱和、批量哈希——没有循环可依；SLP 的回答是换种找法：在基本块里找「同一指令、相邻操作数」的种籽，从种籽向上打包成向量语句（Larsen–Amarasinghe, 2000）。二是依赖证不出来：两个指针可能重叠，静态分析给不出证明；<a href="/cs/alias-analysis">别名分析</a>越保守，能直接向量化的循环越少。证明失败不等于运行时失败——这是版本化要补的缺口。</p><p><span class="marginnote">数字实例：AVX-512 的一条向量指令宽 512 位，装 \\(512/32 = 16\\) 个 float。处理 100 个元素的循环：6 个满向量吃 96 个，剩 4 个由掩码指令收尾——没有掩码的时代，这 4 个要单独写一段标量「尾巴循环」，代码体积与分支预测都跟着遭殃。</span></p><h3 id="版本化与掩码" tabindex="-1">版本化与掩码 <a class="header-anchor" href="#版本化与掩码" aria-label="Permalink to &quot;版本化与掩码&quot;">​</a></h3><p>版本化把证明搬到运行时：生成一段区间重叠检查，通过则走向量版，失败则落回标量版。代价是一份循环两个副本加一次检查，只配放在热循环上。掩码走另一条路：AVX-512 的 opmask 给向量指令一个逐通道开关，「带条件的标量运算」直接折成一条掩码指令，连分支都不用拆。<a href="/cs/rvv-vector">变长 ISA</a>（SVE、RVV）再推一步：向量长度编译期未知，余数处理不再是尾循环，而是按硬件当前宽度自然分块。</p><p><span class="marginnote">AVX-512 有 8 个 opmask 寄存器（k0–k7），掩码 load/store 让 16 路浮点循环的余数不再需要单独的标量尾巴；SVE 与 RVV 把长度也变成运行时事实。同一份自动向量化代码因此能在不同宽度的机器上跑——宽度不再是编译期承诺。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成本模型把几条路排序。循环路线的账：向量寄存器压力——向量区间更长更宽，<a href="/cs/cg-register-allocation-deep">分配</a>的代价表直接恶化；gather/scatter 通常比连续 load 贵好几倍，间接访存的循环常常不值得。SLP 路线的账：打包与重排的成本——shuffle 是向量指令里最贵的一类，省下的算术盖不住重排就是负优化；shuffle 模式的好坏取决于<a href="/cs/cg-instruction-selection">选择器</a>有没有对应模式，两课在此接上。归约要重结合许可：浮点加法不满足结合律，改次序需要 <a href="/cs/fast-math">fast-math</a> 的授权，没有授权就沉默地放弃。</p><p><span class="marginnote">术语翻译：gather/scatter 是「按下标数组访存」的向量版——<code>a[idx[i]]</code> 一口气搬一撮位置不连续的数。连续 load 一次读一整条 cache 行物尽其用；gather 几乎每个通道各缺一次缓存，所以贵好几倍。</span></p><p><span class="marginnote">常见误区：初学者容易以为「编译器没向量化是坏了」，更常见的原因是浮点归约——把 <code>(a+b)+(c+d)</code> 换次序会改变舍入结果，没有 fast-math 授权编译器宁可保持标量也不动它。性能就地损失时，先看编译报告里放弃了哪条理由。</span></p>',13)),(t(),i(n,null,{default:s(()=>[l(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOOP%5B%22%E6%A0%87%E9%87%8F%E5%BE%AA%E7%8E%AF%20%2F%20%E7%9B%B4%E7%BA%BF%E4%BB%A3%E7%A0%81%22%5D%20--%3E%20TEST%7B%22%E4%BE%9D%E8%B5%96%E4%B8%8E%E5%88%AB%E5%90%8D%E5%8F%AF%E8%AF%81%EF%BC%9F%22%7D%0A%20%20TEST%20--%3E%7C%E5%8F%AF%E8%AF%81%7C%20VEC%5B%22%E7%9B%B4%E6%8E%A5%E5%90%91%E9%87%8F%E5%8C%96%22%5D%0A%20%20TEST%20--%3E%7C%E4%B8%8D%E5%8F%AF%E8%AF%81%7C%20VER%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E7%89%88%E6%9C%AC%E5%8C%96%EF%BC%9A%E6%A3%80%E6%9F%A5%20%2B%20%E5%8F%8C%E7%89%88%E6%9C%AC%22%5D%0A%20%20VER%20--%3E%20VEC%0A%20%20VEC%20--%3E%20TAIL%5B%22%E5%B0%BE%E9%83%A8%EF%BC%9A%E6%8E%A9%E7%A0%81%20%2F%20%E5%8F%98%E9%95%BF%E5%88%86%E5%9D%97%20%2F%20%E6%A0%87%E9%87%8F%22%5D%0A%20%20TAIL%20--%3E%20CM%7B%22%E6%88%90%E6%9C%AC%E6%A8%A1%E5%9E%8B%EF%BC%9A%E6%94%B6%E7%9B%8A%E5%87%8F%E6%88%90%E6%9C%AC%EF%BC%9F%22%7D%0A%20%20CM%20--%3E%7C%E6%98%AF%7C%20OUT%5B%22%E5%90%91%E9%87%8F%E6%8C%87%E4%BB%A4%22%5D%0A%20%20CM%20--%3E%7C%E5%90%A6%7C%20SCALAR%5B%22%E4%BF%9D%E6%8C%81%E6%A0%87%E9%87%8F%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("自动向量化改变的是下游一切输入的形状：DAG 里多了 shuffle 与宽 load，调度器面对更长的延迟链，分配器面对更宽的区间。「向量化之后再调度、再分配」不是顺序陈述而是因果陈述——宽度在每一处都付账。跨栏对照："),e("a",{href:"/cs/gpu-simt"},"SIMT"),E(" 把「一条指令吃一批数据」做成 warp 粒度的隐式事实，分支分歧由硬件掩码，占用率的账在 "),e("a",{href:"/llm/cuda-occupancy"},"CUDA 一课"),E("算过；CPU 向量化是在 ISA 上显式做同一件事，掩码、变长与打包成本全落在编译器头上。谁把事实做成隐式、谁做成显式，决定了各自编译器要管多少。")],-1)),(t(),i(n,null,{default:s(()=>[l(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAME%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E5%8E%9F%E7%90%86%EF%BC%9A%E4%B8%80%E6%9D%A1%E6%8C%87%E4%BB%A4%E5%90%83%E4%B8%80%E6%89%B9%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20CPU%5B%22CPU%20%2F%20SIMD%EF%BC%9A%E6%98%BE%E5%BC%8F%22%5D%0A%20%20SAME%20--%3E%20GPU%5B%22GPU%20%2F%20SIMT%EF%BC%9A%E9%9A%90%E5%BC%8F%22%5D%0A%20%20CPU%20--%3E%20C1%5B%22%E7%BC%96%E8%AF%91%E5%99%A8%E9%80%89%E5%AE%BD%E6%8C%87%E4%BB%A4%E3%80%81%E6%8E%92%20shuffle%E3%80%81%E4%BB%98%E6%8E%A9%E7%A0%81%22%5D%0A%20%20GPU%20--%3E%20G1%5B%22%E7%A1%AC%E4%BB%B6%E6%8C%89%20warp%20%E6%89%A7%E8%A1%8C%EF%BC%8C%E5%88%86%E6%94%AF%E5%88%86%E6%AD%A7%E7%A1%AC%E4%BB%B6%E6%8E%A9%22%5D%0A%20%20C1%20--%3E%20COST%5B%22%E8%B4%A6%E5%8D%95%E8%90%BD%E5%9C%A8%E7%BC%96%E8%AF%91%E5%99%A8%E4%B8%8E%E6%88%90%E6%9C%AC%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20G1%20--%3E%20COST2%5B%22%E8%B4%A6%E5%8D%95%E8%90%BD%E5%9C%A8%E5%8D%A0%E7%94%A8%E7%8E%87%E4%B8%8E%E8%B0%83%E5%BA%A6%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲依赖方向测试的代数——GCD 判定与方向向量是循环理论课的对象——也不覆盖多边形模型，重写循环嵌套超出「打 SIMD」的范围。自动化的失败模式是沉默：成本模型说不，编译器不说话，性能就地损失；人工逃生门是 intrinsics，但 intrinsic 钉死宽度与 ISA，与变长目标相克，迁移成本自己付。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>循环向量化靠依赖证明，SLP 换种籽：同一指令、相邻操作数。</li><li>证明不了用版本化：运行时检查加双版本，只配热循环。</li><li>掩码与变长把余数、条件与宽度都变成向量指令的参数。</li><li>成本模型决定值不值：shuffle、gather 与向量压力都是账单。</li><li>出处：Allen and Kennedy 的教材；Larsen and Amarasinghe, 2000；AVX-512 / SVE / RVV 架构手册。</li></ul>',4))])}const S=o(c,[["render",C]]);export{u as __pageData,S as default};
